/*

Submission for @sableraph's #WCCChallenge
Topic: Waves

Some SDF shenanigans, interpolating between two different ones
Drawing to a graphics buffer to make it look the same on different screen dimension

*/

let pg;
let S = 730; // size of the buffer, changing this has drastic effects on the sketch

function setup() {
  w = max(windowWidth, windowHeight)
  createCanvas(w, w);

  pg = createGraphics(S, S)

  pad = S/12

	// number of rows and columns
  gX = 25
  gY = 25

	// spacing of the points
  gsx = (S - pad * 2 ) / gX
  gsy = (S - pad * 2 ) / gY

  loopLength = 200 // number of frames
}

function draw(){
  t = (frameCount%loopLength)/loopLength
  sinput = map(t, 0, 1, 0, TAU)

  makeWave()
  image(pg,0,-windowHeight/2,w,w)
}

function makeWave() {
  pg.background(0,0,50,30);

  for(let x = pad; x < S-pad+1; x+=(Math.max(0.001, Math.abs(gsx)) || 1)){
    for(let y = pad; y < S-pad+1; y+=(Math.max(0.001, Math.abs(gsy)) || 1)){


      // A distance function
      var d = dist(x,y,x,x)/2

      // A number that alternates between 0 <-and-> 1
      var lerper = map(sin(sinput),-1,1,0,1)

      // Some numbers to play with
      var Xmod = 15
      var Ymod = 15



      // Shape SDF 1
      var shapeMod1 = sinput + x + y + sin(sinput + d)

      // Shape SDF 2
      var shapeMod2 = sinput + d + d*x/10000 + y

      // Interpolation between the two SDF functions
      var lerpedMod = (sin(shapeMod1)*lerper + sin(shapeMod2)*(1-lerper))

      pg.strokeWeight(17 + 17 * lerpedMod)



      // Sinusoidal color palettes

      // Color SDF 1
      var colorMod1 = (togg) =>
                sin(sinput + x*Xmod + y*Ymod)*togg
                + cos(sinput + x*Xmod + y*Ymod)*(1 - togg)

      // Color SDF 2
      var colorMod2 = (togg) =>
                sin(shapeMod2)*togg + cos(shapeMod2)*(1-togg)


      // Interpolation between the two color SDF functions
      var lerpedColorMod = (togg) =>
              colorMod1(togg)*lerper + colorMod2(togg)*(1-lerper)

      // Assign colors
      pg.stroke(127.5 + 127.5 * lerpedColorMod(1),
              127.5 + 127.5 * lerpedColorMod(0),
              127.5 - 127.5 * lerpedColorMod(lerper))


      // The actual points
      pg.point(x, y)
    }
  }
}



